/**
 * Agnes Image 2.5 Flash for DeepSeek Harness.
 *
 * Registers one model-facing tool, `agnes_generate_image`, that covers
 * text-to-image, image-to-image, and multi-image composition. Generated bytes
 * are saved inside the session workspace and (when the active model accepts
 * image input) attached to the tool result so the model can inspect them.
 *
 * Only this entry module imports harness packages; `lib/*` stays plain Node so
 * unit tests and the live smoke test can run outside the host.
 */

import { defineTool } from '@deepseek-ai/dsh-tools'
import { basename, dirname, extname, isAbsolute, join, resolve as resolvePath } from 'node:path'
import { existsSync } from 'node:fs'
import { mkdir, writeFile } from 'node:fs/promises'
import { randomBytes } from 'node:crypto'
import {
  AgnesImageClient,
  AGNES_DEFAULT_BASE_URL,
  AGNES_DEFAULT_MODEL,
  AGNES_RATIOS,
  AGNES_SIZES,
} from './lib/agnes-client.js'
import {
  defaultImageFileName,
  extensionFor,
  formatBytes,
  imageDimensions,
  sniffImageMediaType,
  toDataUri,
} from './lib/image.js'

/** Cordis plugin name used in loader diagnostics. */
export const name = 'agnes-image'
/** The tool registry must exist before registration; credentials resolve the key. */
export const inject = ['tools', 'credentials']

const DEFAULT_API_KEY_ENV = 'AGNES_API_KEY'
const DEFAULT_OUTPUT_DIR = 'assets/generated'
const MAX_INPUT_IMAGE_BYTES = 32 * 1024 * 1024

const IMAGE_VALUE_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    attachmentId: { type: 'string', required: true },
    mediaType: { type: 'string', required: true },
    bytes: { type: 'integer', required: true },
    width: { type: 'integer', required: true },
    height: { type: 'integer', required: true },
    name: { type: 'string' },
  },
}

const OUTPUT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    path: { type: 'string', required: true },
    url: { type: 'string' },
    model: { type: 'string', required: true },
    size: { type: 'string', required: true },
    ratio: { type: 'string', required: true },
    mediaType: { type: 'string', required: true },
    bytes: { type: 'integer', required: true },
    width: { type: 'integer' },
    height: { type: 'integer' },
    imageCount: { type: 'integer', required: true },
    attached: { type: 'boolean', required: true },
    image: IMAGE_VALUE_SCHEMA,
  },
}

/** Merge plugin config over the documented defaults. */
function resolveSettings(config) {
  const c = config ?? {}
  const apiKeyEnv = String(c.apiKeyEnv ?? DEFAULT_API_KEY_ENV).trim()
  if (apiKeyEnv.length === 0) throw new Error('agnes-image: apiKeyEnv must be a non-empty credential reference')
  const baseURL = String(c.baseURL ?? AGNES_DEFAULT_BASE_URL).trim().replace(/\/+$/u, '')
  const timeoutMs = Number(c.timeoutMs ?? 300_000)
  if (!Number.isFinite(timeoutMs) || timeoutMs < 1_000) throw new Error('agnes-image: timeoutMs must be at least 1000')
  const maxInputImages = Number(c.maxInputImages ?? 8)
  return {
    apiKeyEnv,
    baseURL,
    model: String(c.model ?? AGNES_DEFAULT_MODEL).trim(),
    defaultSize: AGNES_SIZES.includes(c.defaultSize) ? c.defaultSize : '2K',
    defaultRatio: AGNES_RATIOS.includes(c.defaultRatio) ? c.defaultRatio : '1:1',
    outputDir: String(c.outputDir ?? DEFAULT_OUTPUT_DIR).trim() || DEFAULT_OUTPUT_DIR,
    timeoutMs,
    maxInputImages: Number.isFinite(maxInputImages) && maxInputImages > 0 ? Math.floor(maxInputImages) : 8,
    attachImage: c.attachImage !== false,
    allowOutsideWorkspace: c.allowOutsideWorkspace === true,
  }
}

/** The session workspace directory, falling back to the process cwd. */
async function resolveCwd(ctx, exec) {
  const workingDirectory = ctx.get('workingDirectory')
  if (workingDirectory !== undefined && exec.agent !== undefined) {
    try {
      return await workingDirectory.ensure(exec.agent, exec.signal)
    } catch {
      // Fall through to the host cwd; the tool still reports a usable path.
    }
  }
  return process.cwd()
}

/** Resolve one path through the mounted filesystem backend when there is one. */
async function resolveTarget(ctx, filePath, cwd, signal) {
  const fs = ctx.get('fs')
  if (fs !== undefined) return await fs.resolve(filePath, { cwd, signal })
  const absolute = isAbsolute(filePath) ? filePath : resolvePath(cwd, filePath)
  return { targetKey: absolute, displayPath: filePath }
}

/** Whether a target stays inside the workspace root (or outside is allowed). */
async function assertInsideWorkspace(ctx, target, cwd, signal, settings) {
  if (settings.allowOutsideWorkspace) return
  const fs = ctx.get('fs')
  if (fs === undefined || typeof fs.contains !== 'function') return
  const root = await fs.resolve('.', { cwd, signal })
  if (!fs.contains(root, target)) {
    throw new Error('output_path must stay inside the workspace; set allowOutsideWorkspace in the plugin config to write elsewhere')
  }
}

/** Convert one model-supplied image reference into a URL or data URI the API accepts. */
async function imageReferenceToApiInput(ctx, reference, exec, cwd) {
  const value = reference.trim()
  if (value.length === 0) throw new Error('images entries must be non-empty strings')
  if (/^https:\/\//iu.test(value) || /^data:image\/[a-z0-9.+-]+;base64,/iu.test(value)) return value
  if (/^http:\/\//iu.test(value)) {
    throw new Error('input image URLs must use HTTPS; download the image and pass a local path instead')
  }
  const fs = ctx.get('fs')
  if (fs === undefined) throw new Error('local input images require a mounted filesystem backend')
  const target = await fs.resolve(value, { cwd, signal: exec.signal })
  const info = await fs.stat(target, exec.signal)
  if (info === undefined) throw new Error(`input image not found: ${value}`)
  if (info.type !== 'file') throw new Error(`input image is not a regular file: ${value}`)
  if (info.size > MAX_INPUT_IMAGE_BYTES) {
    throw new Error(`input image is larger than ${Math.round(MAX_INPUT_IMAGE_BYTES / (1024 * 1024))} MB: ${value}`)
  }
  const bytes = Buffer.from(await fs.readBytes(target, exec.signal, MAX_INPUT_IMAGE_BYTES))
  const mediaType = sniffImageMediaType(bytes)
  if (mediaType === undefined) throw new Error(`input file is not a PNG/JPEG/WebP/GIF image: ${value}`)
  return toDataUri(bytes, mediaType)
}

/** Resolve the active route and whether it declares image input. */
async function routeSupportsImage(ctx, exec) {
  try {
    const llm = ctx.get('llm')
    if (llm === undefined || typeof llm.resolveModelInfo !== 'function') return false
    const session = exec.agent?.session
    const routed = typeof session?.requestHeader === 'function' ? session.requestHeader()?.config : undefined
    const provider = routed?.provider ?? exec.agent?.options?.provider
    const model = routed?.model ?? exec.agent?.options?.model
    if (provider === undefined || model === undefined) return false
    const info = await llm.resolveModelInfo(provider, model, exec.signal)
    return Array.isArray(info?.inputModalities) && info.inputModalities.includes('image')
  } catch {
    return false
  }
}

/** Format the user/model-facing summary that sits beside the optional image block. */
function formatResult(value) {
  const dimensions = value.width !== undefined && value.height !== undefined ? `, ${value.width}x${value.height}px` : ''
  const lines = [
    `Generated ${value.imageCount} image with ${value.model} (${value.size}, ${value.ratio}${dimensions}, ${formatBytes(value.bytes)}).`,
    `Saved to: ${value.path}`,
  ]
  if (value.url !== undefined) lines.push(`Source URL: ${value.url}`)
  if (value.attached) lines.push('The generated image is attached so you can inspect it directly.')
  else lines.push('The image was saved but not attached to the conversation (the active model may not accept image input).')
  return lines.join('\n')
}

/** Register the tool on the harness registry. */
export function apply(ctx, config) {
  const settings = resolveSettings(config)
  const client = new AgnesImageClient({
    baseURL: settings.baseURL,
    model: settings.model,
    timeoutMs: settings.timeoutMs,
    resolveApiKey: async () => {
      const credentials = ctx.get('credentials')
      if (credentials !== undefined) {
        const hit = await credentials.resolve(settings.apiKeyEnv)
        if (typeof hit?.value === 'string' && hit.value.length > 0) return hit.value
      }
      return process.env[settings.apiKeyEnv]
    },
  })

  ctx.tools.register(defineTool({
    name: 'agnes_generate_image',
    description:
      'Generate or edit an image with Agnes Image 2.5 Flash (agnes-image-2.5-flash). '
      + 'Text-to-image: pass prompt + size + ratio. Image-to-image or multi-image composition: also pass images '
      + '(public HTTPS URLs, data URIs, or workspace file paths). The image is saved as a file and its path is returned; '
      + 'use size tiers 1K/2K/3K/4K with an aspect ratio (they are the model\'s native sizes). '
      + 'Generation usually takes several seconds and may take up to a few minutes.',
    parameters: {
      prompt: {
        type: 'string',
        required: true,
        description: 'What to generate or how to edit the reference image(s). For edits, name what to keep and what to change.',
      },
      size: {
        type: 'string',
        enum: AGNES_SIZES,
        description: 'Output resolution tier (default 2K). 1K=1024px-class, 4K=4096px-class. Prefer 1K/2K unless large output is needed.',
      },
      ratio: {
        type: 'string',
        enum: AGNES_RATIOS,
        description: 'Aspect ratio paired with size (default 1:1).',
      },
      images: {
        type: 'array',
        items: { type: 'string' },
        description: 'Optional reference images for image-to-image or composition: public HTTPS URLs, data URIs, or workspace-relative/absolute file paths.',
      },
      output_path: {
        type: 'string',
        description: 'Optional output file path, relative to the workspace (or absolute inside it). Defaults to assets/generated/agnes-<timestamp>-<id>.png.',
      },
      overwrite: {
        type: 'boolean',
        description: 'Allow replacing an existing output_path file (default false).',
      },
    },
    output: {
      schema: OUTPUT_SCHEMA,
      render: (_args, value) => {
        const content = [{ type: 'text', text: formatResult(value) }]
        if (value.image !== undefined) content.push({ type: 'image', attachment: value.image })
        return content
      },
      presentationMeta: (_args, value) => ({ path: value.path }),
    },
    isConcurrencySafe: () => true,
    async execute(args, exec) {
      const prompt = typeof args.prompt === 'string' ? args.prompt.trim() : ''
      if (prompt.length === 0) throw new Error('prompt must be a non-empty string')
      if (args.images !== undefined && !Array.isArray(args.images)) {
        throw new Error('images must be an array of strings')
      }
      const images = Array.isArray(args.images) ? args.images : []
      if (!images.every((entry) => typeof entry === 'string')) throw new Error('images must be an array of strings')
      if (images.length > settings.maxInputImages) {
        throw new Error(`at most ${settings.maxInputImages} reference images are supported`)
      }

      const cwd = await resolveCwd(ctx, exec)
      const size = AGNES_SIZES.includes(args.size) ? args.size : settings.defaultSize
      const ratio = AGNES_RATIOS.includes(args.ratio) ? args.ratio : settings.defaultRatio

      const apiImages = []
      for (const reference of images) {
        apiImages.push(await imageReferenceToApiInput(ctx, reference, exec, cwd))
      }

      const requestedPath = typeof args.output_path === 'string' && args.output_path.trim().length > 0
        ? args.output_path.trim()
        : join(settings.outputDir, defaultImageFileName(new Date(), randomBytes(3).toString('hex')))
      const target = await resolveTarget(ctx, requestedPath, cwd, exec.signal)
      await assertInsideWorkspace(ctx, target, cwd, exec.signal, settings)

      const fs = ctx.get('fs')
      if (fs !== undefined) {
        const existing = await fs.stat(target, exec.signal)
        if (existing !== undefined && args.overwrite !== true) {
          throw new Error(`output file already exists: ${target.displayPath}; pass overwrite: true or choose another output_path`)
        }
        if (existing !== undefined && existing.type !== 'file') {
          throw new Error(`output path is not a regular file: ${target.displayPath}`)
        }
      }

      const generated = await client.generate({ prompt, size, ratio, images: apiImages, signal: exec.signal })
      const bytes = Buffer.from(generated.bytes)
      const mediaType = sniffImageMediaType(bytes)
      if (mediaType === undefined) {
        throw new Error('Agnes returned bytes that are not a PNG/JPEG/WebP/GIF image')
      }

      const processPath = fs !== undefined && typeof fs.processPath === 'function'
        ? fs.processPath(target)
        : (isAbsolute(target.targetKey) ? String(target.targetKey) : resolvePath(cwd, requestedPath))
      const expectedExtension = extensionFor(mediaType)
      const currentExtension = extname(processPath).toLowerCase()
      const finalPath = currentExtension === expectedExtension
        ? processPath
        : `${currentExtension.length === 0 ? processPath : processPath.slice(0, -currentExtension.length)}${expectedExtension}`

      if (args.overwrite !== true && existsSync(finalPath)) {
        throw new Error(`output file already exists: ${finalPath}; pass overwrite: true or choose another output_path`)
      }

      await mkdir(dirname(finalPath), { recursive: true })
      await writeFile(finalPath, bytes)

      let attachment
      let dimensions = imageDimensions(bytes, mediaType)
      const attachments = ctx.get('attachments')
      if (attachments !== undefined && settings.attachImage) {
        try {
          const ref = await attachments.saveImage({ data: bytes, mediaType, name: basename(finalPath) })
          attachment = {
            attachmentId: ref.attachmentId,
            mediaType: ref.mediaType,
            bytes: ref.bytes,
            width: ref.width,
            height: ref.height,
            ...ref.name === undefined ? {} : { name: ref.name },
          }
          dimensions = { width: ref.width, height: ref.height }
        } catch (error) {
          ctx.logger?.warn?.('agnes-image: generated image saved but could not be attached: %s', error?.message ?? String(error))
        }
      }

      const attach = attachment !== undefined && await routeSupportsImage(ctx, exec)
      return {
        path: finalPath,
        ...generated.url === undefined ? {} : { url: generated.url },
        model: generated.model,
        size,
        ratio,
        mediaType: attachment?.mediaType ?? mediaType,
        bytes: bytes.byteLength,
        ...dimensions === undefined ? {} : { width: dimensions.width, height: dimensions.height },
        imageCount: 1,
        attached: attach,
        ...attach ? { image: attachment } : {},
      }
    },
  }))
}
